//! 既存の元点がLPの端点初期化に使えるかだけを調べる。最適化しない。
use mip_codex::mps;
fn main(){let a:Vec<_>=std::env::args().collect();let m=mps::read(&a[1]).unwrap();let r:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[2]).unwrap()).unwrap();let x:Vec<_>=m.variables.iter().map(|v|r["values"][&v.name].as_f64().unwrap()).collect();assert!(m.check(&x,true,1e-7).is_ok());let mut endpoint=0;let mut interior=vec![];for(j,(v,&z))in m.variables.iter().zip(&x).enumerate(){let [lo,hi]=if v.integer{v.integer_bounds.unwrap_or([v.lower.map(f64::ceil),v.upper.map(f64::floor)])}else{[v.lower,v.upper]};if lo==Some(z)||hi==Some(z)||(lo.is_none()&&hi.is_none()&&z==0.){endpoint+=1;}else{interior.push((j,z,lo,hi));}}println!("{}",serde_json::json!({"variables":m.variables.len(),"endpoint":endpoint,"interior":interior.len(),"examples":interior.iter().take(12).collect::<Vec<_>>(),"objective":m.objective(&x),"claim":"shape diagnostic only; no LP status/bound"}));}
